"""离线原型 v3：+ 与图片块去重；跑多篇 PDF 看误报。"""
import pymupdf, sys

BAND, MAX_THICK, GAP = 0.14, 2.0, 6.0

def vis_text(page):
    out = []
    for b in page.get_text("dict")["blocks"]:
        if b.get("type") != 0: continue
        for l in b["lines"]:
            for s in l["spans"]:
                if s["text"].strip() and s["color"] != 0xFFFFFF:
                    out.append(pymupdf.Rect(s["bbox"]))
    return out

def analyze(path, verbose=True):
    doc = pymupdf.open(path)
    cand = 0
    for pno, page in enumerate(doc, 1):
        W, H = page.rect.width, page.rect.height
        vis = vis_text(page)
        imgs = [pymupdf.Rect(b["bbox"]) for b in page.get_text("dict")["blocks"] if b.get("type") == 1]
        colw = max((t.x1 for t in vis), default=W) - min((t.x0 for t in vis), default=0)
        shapes = []
        for d in page.get_drawings():
            r = d["rect"]
            if (r.height <= MAX_THICK and r.width > 8) or (r.width <= MAX_THICK and r.height > 8):
                continue
            if r.y1 <= H * BAND or r.y0 >= H * (1 - BAND):
                if any((r & i).get_area() > 0.5 for i in imgs):   # 与图片块重叠 → 已有 figure
                    continue
                shapes.append(r)
        shapes.sort(key=lambda r: (r.y0, r.x0))
        clusters = []
        for r in shapes:
            for i, c in enumerate(clusters):
                m = c | r
                if m.height < 40 and r.x0 < c.x1 + GAP and r.x1 > c.x0 - GAP and abs(r.y0 - c.y0) < 20:
                    clusters[i] = m; break
            else:
                clusters.append(pymupdf.Rect(r))
        for c in clusters:
            hit = [t for t in vis if (c & t).get_area() > 0.5]
            ok = (not hit) and (c.width / colw < 0.40)
            if ok:
                cand += 1
                if verbose: print(f"   ✅ p{pno} ({c.x0:6.1f},{c.y0:6.1f})-({c.x1:6.1f},{c.y1:6.1f}) w={c.width:5.1f} h={c.height:5.1f}")
            elif verbose:
                why = "压可见文字" if hit else f"太宽 {c.width/colw:.0%}"
                print(f"   ✗  p{pno} ({c.x0:6.1f},{c.y0:6.1f})-({c.x1:6.1f},{c.y1:6.1f}) — {why}")
    return cand, len(doc)

for path in sys.argv[1:]:
    print("=====", path.split("/")[-1])
    n, pages = analyze(path)
